function EXTRACT-FACTOR(N, s):
    g <- GCD(s mod N, N)            # Euclidean algorithm, O(log^2 N)
    if 1 < g < N then return g      # g is p or q, a proper nontrivial factor
    else return FAIL                # g = 1 (s hit neither prime) or g = N (s hit both)

function THREE-SUM-WITNESS(N, a, b, c):
    return EXTRACT-FACTOR(N, a + b + c)

Correctness (classification): for distinct primes p, q and any integer s,
    gcd(s, pq) = pq  if p | s and q | s
    gcd(s, pq) = p   if p | s and q does not divide s
    gcd(s, pq) = q   if q | s and p does not divide s
    gcd(s, pq) = 1   otherwise.

