function FALLING-FACTORIAL(p, m):
    out <- 1
    for i from 0 to m-1 do out <- out * (p - i)
    return out                          # exact count of collision-free evaluations

function MAJORITY-COLLISION-FREE(p, m):
    return p^m < 2 * FALLING-FACTORIAL(p, m)

function RANDOMISED-THRESHOLD(p):
    m <- 1
    while MAJORITY-COLLISION-FREE(p, m) do m <- m + 1
    return m                            # empirically m is about 1.18 * sqrt(p)

Theorem: 2*C(m,2) < p implies p^m < 2 * FALLING-FACTORIAL(p, m);
in particular m^2 < p implies a strict majority of collision-free evaluations.

